import co.nexus.research.*;import java.io.*;import java.util.*;
public class CognitiveTest{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+s);}
 public static void main(String[] args)throws Exception{CognitiveCore c=new CognitiveCore(42);check(CognitiveCore.PARAMETERS==2277632,"parameter count");float[] s=new float[128];s[0]=1;CognitiveCore.Observation o=new CognitiveCore.Observation(s,EnumSet.of(CognitiveCore.Action.READ));float[] t={.95f,.9f,.05f,.95f};float before=err(c.rank(o).get(0).heads,t);for(int i=0;i<160;i++)c.learn(o,CognitiveCore.Action.READ,t);float after=err(c.rank(o).get(0).heads,t);check(after<before,"neural learning");check(c.rank(o).size()==1,"action mask");check(c.rank(new CognitiveCore.Observation(s,Collections.emptySet())).isEmpty(),"empty mask");ByteArrayOutputStream out=new ByteArrayOutputStream();c.write(out);CognitiveCore restored=CognitiveCore.read(new ByteArrayInputStream(out.toByteArray()));check(Arrays.equals(c.rank(o).get(0).heads,restored.rank(o).get(0).heads),"checkpoint exact");long updates=c.updates;for(int episode=0;episode<3;episode++){CognitiveArena a=new CognitiveArena(episode);while(!a.done){CognitiveCore.Observation obs=a.observe();CognitiveCore.Decision d=c.choose(obs,false);a.step(d.action);}check(a.steps<=80,"bounded episode "+episode);}check(c.updates==updates,"evaluation does not train");CognitiveArena a=new CognitiveArena(123);for(int j=0;j<20&&!a.done;j++){CognitiveCore.Observation obs=a.observe();CognitiveCore.Decision d=c.choose(obs,true);c.learn(obs,d.action,a.step(d.action));}check(c.updates>updates,"autonomous simulator outcomes update model");System.out.println("MSE "+before+" -> "+after);}
 static float err(float[] a,float[] b){float s=0;for(int i=0;i<4;i++)s+=(a[i]-b[i])*(a[i]-b[i]);return s/4;}
}
